import { createFileRoute, Link, redirect } from "@tanstack/react-router";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useEffect, useMemo, useRef, useState } from "react";
import { CalendarDays, Camera, Check, ClipboardCheck, Eye, FileText, History, Home, Images, MapPin, Package, Pencil, Plus, Search, ShieldCheck, Sparkles, UsersRound, X } from "lucide-react";
import { toast } from "sonner";

import { supabase } from "@/integrations/supabase/client";
import { MyioAppLogo } from "@/components/myio-app-logo";
import { AddressAutocomplete } from "@/components/address-autocomplete";
import { ConfirmDeleteButton } from "@/components/confirm-delete-button";
import { SiteSurveyLucManager } from "@/components/site-survey-luc-manager";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { suggestShopNameFromFacade } from "@/lib/site-survey-ai.functions";

const PERMISSIONS = [
  ["site_survey_visitas_minhas", "Minhas visitas"],
  ["site_survey_visitas_todas", "Todas as visitas"],
  ["site_survey_agendar", "Criar e agendar"],
  ["site_survey_editar", "Editar agendamentos"],
  ["site_survey_executar", "Executar e preencher"],
  ["site_survey_revisar", "Revisar e reabrir"],
  ["site_survey_excluir", "Excluir visitas"],
  ["site_survey_usuarios", "Usuários"],
  ["site_survey_perfis", "Perfis de acesso"],
  ["site_survey_logs", "Logs"],
  ["site_survey_configuracoes", "Modelos de checklist"],
  ["site_survey_cadastro", "Cadastro e Diversos"],
] as const;

type VisitStatus = "agendada" | "em_andamento" | "em_revisao" | "concluida" | "cancelada";
type Visit = {
  id: string; survey_number: number; client_id: string | null; client_unit_id: string | null; project_id: string | null;
  technician_id: string; created_by: string; template_id: string | null; status: VisitStatus; scheduled_start: string;
  scheduled_end: string | null; address: string; contact_name: string | null; contact_phone: string | null; notes: string | null;
  review_notes: string | null; started_at: string | null; submitted_at: string | null; completed_at: string | null;
  luc_number: string | null; shop_name: string | null; environments: unknown;
};
type Named = { id: string; name: string };
type ClientOption = Named & { category_id: string | null };
type ProjectOption = Named & { client_id: string | null };
type ClientCategory = Named;
type Profile = { id: string; full_name: string; email: string | null };
type Template = { id: string; name: string; description: string | null; active: boolean };
type Section = { id: string; template_id: string; title: string; description: string | null; position: number };
type Question = { id: string; section_id: string; prompt: string; question_type: "checkbox" | "text" | "textarea" | "number" | "select"; required: boolean; options: unknown; position: number; active: boolean };
type CatalogItem = Named & { category: "material" | "equipamento"; active: boolean; position: number };

const STATUS: Record<VisitStatus, string> = { agendada: "Agendada", em_andamento: "Em andamento", em_revisao: "Em revisão", concluida: "Concluída", cancelada: "Cancelada" };
const STATUS_ORDER: VisitStatus[] = ["agendada", "em_andamento", "em_revisao", "concluida", "cancelada"];

export const Route = createFileRoute("/_authenticated/site-survey")({
  beforeLoad: async ({ context }) => {
    const { data } = await supabase.from("user_app_access").select("app_key").eq("user_id", context.user.id).eq("app_key", "site_survey").maybeSingle();
    if (!data) throw redirect({ to: "/portal" });
  },
  component: SiteSurveyPage,
  head: () => ({ meta: [
    { title: "Site Survey | myio ERP" },
    { name: "description", content: "Agendamento, execução e acompanhamento de visitas técnicas de implantação." },
    { property: "og:title", content: "Site Survey | myio ERP" },
    { property: "og:description", content: "Visitas técnicas de implantação na plataforma myio ERP." },
    { property: "og:type", content: "website" },
    { name: "twitter:card", content: "summary" },
  ] }),
});

function SiteSurveyPage() {
  const qc = useQueryClient();
  const [section, setSection] = useState("visitas");
  const [statusFilter, setStatusFilter] = useState("todos");
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState<Visit | null>(null);
  const { data, isLoading } = useQuery({
    queryKey: ["site-survey-data"],
    queryFn: async () => {
      const { data: auth } = await supabase.auth.getUser();
      if (!auth.user) throw new Error("Sessão não encontrada");
      const [{ data: visits, error }, { data: clients }, { data: clientCategories }, { data: projects }, { data: units }, { data: technicians }, { data: templates }, { data: sections }, { data: questions }, { data: surveyProfile }, { data: surveyPermissions }, { data: erpAdmin }, { data: catalog }, { data: screwdriverTypes }, { data: wrenchSizes }] = await Promise.all([
        supabase.from("site_survey_visits").select("*").order("scheduled_start", { ascending: false }),
        supabase.from("clients").select("id,name,category_id").order("name"),
        supabase.from("client_categories").select("id,name").eq("active", true).order("position"),
        supabase.from("projects").select("id,name,client_id").order("name"),
        supabase.from("client_units").select("id,name,client_id").eq("active", true).order("name"),
        supabase.rpc("get_site_survey_users"),
        supabase.from("site_survey_templates").select("*").order("name"),
        supabase.from("site_survey_sections").select("*").order("position"),
        supabase.from("site_survey_questions").select("*").order("position"),
        supabase.from("site_survey_user_profiles").select("profile_code,is_customized,site_survey_access_profiles(name,site_survey_profile_permissions(permission_key,allowed))").eq("user_id", auth.user.id).maybeSingle(),
        supabase.from("site_survey_user_permissions").select("permission_key,allowed").eq("user_id", auth.user.id),
        supabase.from("erp_admins").select("user_id").eq("user_id", auth.user.id).maybeSingle(),
        supabase.from("site_survey_material_catalog").select("*").order("position").order("name"),
        supabase.from("site_survey_screwdriver_types").select("id,name").eq("active", true).order("position").order("name"),
        supabase.from("site_survey_wrench_sizes").select("id,name").eq("active", true).order("position").order("name"),
      ]);
      if (error) throw error;
      const profile = surveyProfile as unknown as { profile_code: string; is_customized: boolean; site_survey_access_profiles: { name: string; site_survey_profile_permissions: Array<{ permission_key: string; allowed: boolean }> } | null } | null;
      const permissions = new Set<string>(Boolean(erpAdmin) ? PERMISSIONS.map(([key]) => key) : profile?.is_customized ? (surveyPermissions ?? []).filter((item) => item.allowed).map((item) => item.permission_key) : (profile?.site_survey_access_profiles?.site_survey_profile_permissions ?? []).filter((item) => item.allowed).map((item) => item.permission_key));
      return { userId: auth.user.id, visits: (visits ?? []) as Visit[], clients: (clients ?? []) as ClientOption[], clientCategories: (clientCategories ?? []) as ClientCategory[], projects: (projects ?? []) as ProjectOption[], units: (units ?? []) as Array<Named & { client_id: string }>, technicians: (technicians ?? []) as Profile[], templates: (templates ?? []) as Template[], sections: (sections ?? []) as Section[], questions: (questions ?? []) as Question[], catalog: (catalog ?? []) as CatalogItem[], screwdriverTypes: (screwdriverTypes ?? []) as Named[], wrenchSizes: (wrenchSizes ?? []) as Named[], permissions, profileName: profile?.site_survey_access_profiles?.name ?? "Sem perfil", isErpAdmin: Boolean(erpAdmin) };
    },
  });
  const can = (permission: string) => data?.permissions.has(permission) ?? false;
  const names = useMemo(() => ({
    clients: new Map(data?.clients.map((item) => [item.id, item.name])), projects: new Map(data?.projects.map((item) => [item.id, item.name])), technicians: new Map(data?.technicians.map((item) => [item.id, item.full_name || item.email || "Técnico"])),
  }), [data]);
  const filtered = (data?.visits ?? []).filter((visit) => {
    const haystack = [visit.survey_number, names.clients.get(visit.client_id ?? ""), names.projects.get(visit.project_id ?? ""), names.technicians.get(visit.technician_id), visit.address].join(" ").toLocaleLowerCase("pt-BR");
    return (statusFilter === "todos" || visit.status === statusFilter) && haystack.includes(search.toLocaleLowerCase("pt-BR"));
  });
  const invalidate = () => qc.invalidateQueries({ queryKey: ["site-survey-data"] });

  if (isLoading || !data) return <div className="flex min-h-screen items-center justify-center text-muted-foreground">Carregando Site Survey...</div>;
  const tabs = [
    { value: "visitas", label: "Visitas", icon: CalendarDays, allowed: can("site_survey_visitas_minhas") || can("site_survey_visitas_todas") },
    { value: "checklists", label: "Checklists", icon: ClipboardCheck, allowed: can("site_survey_configuracoes") },
    { value: "cadastro", label: "Cadastro", icon: Package, allowed: can("site_survey_cadastro") || can("site_survey_configuracoes") },
    { value: "usuarios", label: "Usuários", icon: UsersRound, allowed: can("site_survey_usuarios") },
    { value: "perfis", label: "Perfis de acesso", icon: ShieldCheck, allowed: can("site_survey_perfis") },
    { value: "logs", label: "Logs", icon: History, allowed: can("site_survey_logs") },
  ].filter((item) => item.allowed);

  return <div className="min-h-screen bg-background">
    <header className="sticky top-0 z-40 border-b border-border bg-card"><div className="mx-auto flex max-w-7xl items-center justify-between gap-3 px-4 py-4 sm:px-6"><Link to="/portal"><MyioAppLogo appName="Site Survey" className="text-base sm:text-2xl" /></Link><div className="flex items-center gap-2"><Badge variant="outline">{data.profileName}</Badge><Button asChild variant="outline" size="icon" title="Início"><Link to="/portal" aria-label="Início"><Home className="h-4 w-4" /></Link></Button></div></div></header>
    <main className="mx-auto max-w-7xl px-4 py-8 sm:px-6">
      {can("site_survey_agendar") ? <div className="mb-6 flex justify-end"><VisitDialog data={data} onSaved={invalidate} /></div> : null}
      <Tabs value={section} onValueChange={setSection}>
        <TabsList className="no-scrollbar mb-6 flex h-auto w-full justify-start overflow-x-auto bg-transparent p-0">{tabs.map(({ value, label, icon: Icon }) => <TabsTrigger key={value} value={value} className="shrink-0"><Icon className="mr-2 h-4 w-4" />{label}</TabsTrigger>)}</TabsList>
        <TabsContent value="visitas">
          <div className="mb-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-5">{STATUS_ORDER.map((status) => <Card key={status}><CardContent className="flex items-center justify-between p-4"><span className="text-sm text-muted-foreground">{STATUS[status]}</span><strong className="text-2xl">{data.visits.filter((visit) => visit.status === status).length}</strong></CardContent></Card>)}</div>
          <div className="mb-4 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar visita, cliente, projeto ou técnico" className="pl-9" /></div><Select value={statusFilter} onValueChange={setStatusFilter}><SelectTrigger className="sm:w-52"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="todos">Todas as situações</SelectItem>{STATUS_ORDER.map((status) => <SelectItem key={status} value={status}>{STATUS[status]}</SelectItem>)}</SelectContent></Select></div>
          <div className="overflow-hidden rounded-md border border-border bg-card"><div className="hidden grid-cols-[90px_1fr_1fr_1fr_150px_90px] gap-3 border-b bg-primary/20 px-4 py-3 text-sm font-semibold lg:grid"><span>Nº</span><span>Cliente / Projeto</span><span>Técnico</span><span>Agendamento</span><span>Situação</span><span>Ações</span></div>{filtered.map((visit) => <div key={visit.id} className="grid gap-3 border-b border-border px-4 py-4 last:border-0 lg:grid-cols-[90px_1fr_1fr_1fr_150px_90px] lg:items-center"><span className="text-sm font-semibold">#{String(visit.survey_number).padStart(6, "0")}</span><div className="min-w-0"><p className="truncate text-sm font-medium">{names.clients.get(visit.client_id ?? "") ?? names.projects.get(visit.project_id ?? "") ?? "—"}</p>{visit.client_id && visit.project_id ? <p className="truncate text-xs text-muted-foreground">{names.projects.get(visit.project_id)}</p> : null}</div><span className="truncate text-sm">{names.technicians.get(visit.technician_id) ?? "—"}</span><div className="text-sm"><p>{new Date(visit.scheduled_start).toLocaleDateString("pt-BR")}</p><p className="text-xs text-muted-foreground">{new Date(visit.scheduled_start).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}</p></div><Badge variant="status" className="w-fit">{STATUS[visit.status]}</Badge><div className="flex gap-1"><Button size="compactIcon" variant="ghost" title="Abrir visita" aria-label="Abrir visita" onClick={() => setSelected(visit)}><Eye className="h-3.5 w-3.5" /></Button>{can("site_survey_editar") ? <VisitDialog data={data} visit={visit} onSaved={invalidate} /> : null}{can("site_survey_excluir") ? <ConfirmDeleteButton title="Excluir visita?" description="Esta ação excluirá a visita, respostas, fotos e histórico." onConfirm={async () => { const { error } = await supabase.from("site_survey_visits").delete().eq("id", visit.id); if (error) return toast.error(error.message); toast.success("Visita excluída"); invalidate(); }} /> : null}</div></div>)}{filtered.length === 0 ? <p className="px-4 py-12 text-center text-sm text-muted-foreground">Nenhuma visita encontrada.</p> : null}</div>
        </TabsContent>
        <TabsContent value="checklists"><ChecklistAdmin data={data} onChanged={invalidate} /></TabsContent>
        <TabsContent value="cadastro"><SurveyCatalogAdmin data={data} onChanged={invalidate} /></TabsContent>
        <TabsContent value="usuarios"><SurveyUsersAdmin /></TabsContent>
        <TabsContent value="perfis"><SurveyProfilesAdmin /></TabsContent>
        <TabsContent value="logs"><SurveyLogs names={names} /></TabsContent>
      </Tabs>
    </main>
    <VisitDetails visit={selected} data={data} onClose={() => setSelected(null)} onChanged={() => { invalidate(); setSelected(null); }} />
  </div>;
}

function VisitDialog({ data, visit, onSaved }: { data: NonNullable<ReturnType<typeof useSurveyDataShape>>; visit?: Visit; onSaved: () => void }) {
  const [open, setOpen] = useState(false);
  const [clientId, setClientId] = useState(visit?.client_id ?? "none");
  const [projectId, setProjectId] = useState(visit?.project_id ?? "none");
  const initialEnvironments = Array.isArray(visit?.environments) ? visit.environments.filter((item): item is string => typeof item === "string") : [];
  const [environments, setEnvironments] = useState<string[]>(initialEnvironments.length ? initialEnvironments : [""]);
  const [shopName, setShopName] = useState(visit?.shop_name ?? "");
  const [analyzingFacade, setAnalyzingFacade] = useState(false);
  const facadeCameraRef = useRef<HTMLInputElement>(null);
  const facadeGalleryRef = useRef<HTMLInputElement>(null);
  const linkedClientId = clientId !== "none" ? clientId : data.projects.find((project) => project.id === projectId)?.client_id ?? null;
  const selectedClient = data.clients.find((client) => client.id === linkedClientId);
  const selectedCategory = data.clientCategories.find((category) => category.id === selectedClient?.category_id);
  const isShopping = selectedCategory?.name.trim().toLocaleLowerCase("pt-BR") === "shoppings";
  const analyzeFacade = async (file?: File) => {
    if (!file) return;
    if (!file.type.startsWith("image/")) return toast.error("Selecione uma foto da fachada.");
    setAnalyzingFacade(true);
    try {
      const imageDataUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("Não foi possível ler a foto.")); reader.readAsDataURL(file); });
      const result = await suggestShopNameFromFacade({ data: { imageDataUrl, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp" | "image/heic" | "image/heif" } });
      setShopName(result.name);
      toast.success("Nome sugerido. Confira antes de salvar.");
    } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível analisar a fachada."); }
    finally { setAnalyzingFacade(false); }
  };
  const save = useMutation({ mutationFn: async (form: HTMLFormElement) => {
    const values = new FormData(form); const projectId = String(values.get("project_id")); const selectedClient = String(values.get("client_id"));
    if (selectedClient === "none" && projectId === "none") throw new Error("Selecione um cliente e/ou projeto.");
    const cleanedEnvironments = environments.map((environment) => environment.trim()).filter(Boolean);
    if (!isShopping && cleanedEnvironments.length === 0) throw new Error("Informe pelo menos um ambiente.");
    const payload = { client_id: selectedClient === "none" ? null : selectedClient, client_unit_id: String(values.get("client_unit_id")) === "none" ? null : String(values.get("client_unit_id")), project_id: projectId === "none" ? null : projectId, technician_id: String(values.get("technician_id")), template_id: String(values.get("template_id")) === "none" ? null : String(values.get("template_id")), scheduled_start: new Date(String(values.get("scheduled_start"))).toISOString(), scheduled_end: values.get("scheduled_end") ? new Date(String(values.get("scheduled_end"))).toISOString() : null, address: String(values.get("address")), contact_name: String(values.get("contact_name")) || null, contact_phone: String(values.get("contact_phone")) || null, notes: String(values.get("notes")) || null, luc_number: isShopping ? String(values.get("luc_number")).trim() : null, shop_name: isShopping ? String(values.get("shop_name")).trim() : null, environments: isShopping ? [] : cleanedEnvironments };
    const result = visit ? await supabase.from("site_survey_visits").update(payload).eq("id", visit.id) : await supabase.from("site_survey_visits").insert({ ...payload, created_by: data.userId });
    if (result.error) throw result.error;
  }, onSuccess: () => { toast.success(visit ? "Visita atualizada" : "Visita agendada"); setOpen(false); onSaved(); }, onError: (error: Error) => toast.error(error.message) });
  const localDate = (value?: string | null) => value ? new Date(value).toISOString().slice(0, 16) : "";
  return <Dialog open={open} onOpenChange={(next) => { setOpen(next); if (next) { setClientId(visit?.client_id ?? "none"); setProjectId(visit?.project_id ?? "none"); setEnvironments(initialEnvironments.length ? initialEnvironments : [""]); setShopName(visit?.shop_name ?? ""); } }}><DialogTrigger asChild><Button size={visit ? "compactIcon" : "default"} variant={visit ? "ghost" : "default"} title={visit ? "Editar visita" : "Nova visita"}>{visit ? <Pencil className="h-3.5 w-3.5" /> : <><Plus className="h-4 w-4" />Nova visita</>}</Button></DialogTrigger><DialogContent className="max-h-[92vh] max-w-3xl overflow-y-auto"><form onSubmit={(event) => { event.preventDefault(); save.mutate(event.currentTarget); }} className="space-y-5"><DialogHeader><DialogTitle>{visit ? "Editar visita" : "Nova visita técnica"}</DialogTitle><DialogDescription>Informe o local, o responsável e o agendamento da vistoria.</DialogDescription></DialogHeader><div className="grid gap-4 sm:grid-cols-2"><FormSelect name="client_id" label="Cliente" value={clientId} onChange={setClientId} options={data.clients} optional /><FormSelect name="client_unit_id" label="Unidade / filial" defaultValue={visit?.client_unit_id ?? "none"} options={data.units.filter((unit) => clientId === "none" || unit.client_id === clientId)} optional /><FormSelect name="project_id" label="Projeto" value={projectId} onChange={setProjectId} options={data.projects} optional /><FormSelect name="technician_id" label="Técnico responsável" defaultValue={visit?.technician_id ?? data.userId} options={data.technicians.map((item) => ({ id: item.id, name: item.full_name || item.email || "Técnico" }))} /><FormSelect name="template_id" label="Checklist" defaultValue={visit?.template_id ?? "none"} options={data.templates.filter((item) => item.active)} optional /><div /></div>{linkedClientId ? <section className="space-y-3 border-t pt-5"><div><h3 className="font-semibold">Identificação da OS</h3>{selectedCategory ? <p className="text-sm text-muted-foreground">Categoria: {selectedCategory.name}</p> : null}</div>{isShopping ? <div className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><LabeledInput name="luc_number" label="Nº do LUC" defaultValue={visit?.luc_number ?? ""} required /><div className="space-y-2"><Label htmlFor="shop-name">Nome da loja</Label><Input id="shop-name" name="shop_name" value={shopName} onChange={(event) => setShopName(event.target.value)} required /></div></div><div className="space-y-2"><Label>Foto da fachada</Label><input ref={facadeCameraRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={(event) => { const file = event.target.files?.[0]; event.target.value = ""; void analyzeFacade(file); }} /><input ref={facadeGalleryRef} type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" className="hidden" onChange={(event) => { const file = event.target.files?.[0]; event.target.value = ""; void analyzeFacade(file); }} /><DropdownMenu><DropdownMenuTrigger asChild><Button type="button" variant="outline" disabled={analyzingFacade}>{analyzingFacade ? <Sparkles className="h-4 w-4" /> : <Camera className="h-4 w-4" />}{analyzingFacade ? "Analisando fachada..." : "Identificar pela fachada"}</Button></DropdownMenuTrigger><DropdownMenuContent align="start" className="min-w-56"><DropdownMenuItem onSelect={() => facadeCameraRef.current?.click()}><Camera className="h-4 w-4" />Tirar foto</DropdownMenuItem><DropdownMenuItem onSelect={() => facadeGalleryRef.current?.click()}><Images className="h-4 w-4" />Escolher da galeria</DropdownMenuItem></DropdownMenuContent></DropdownMenu><div className="flex items-center gap-2 text-xs text-muted-foreground"><Sparkles className="h-3.5 w-3.5" />{analyzingFacade ? "Analisando fachada..." : "A foto sugere o nome; confira e ajuste antes de salvar."}</div></div></div> : <div className="space-y-3"><Label>Ambientes</Label>{environments.map((environment, index) => <div key={index} className="flex items-end gap-2"><div className="flex-1"><Input aria-label={`Ambiente ${index + 1}`} value={environment} onChange={(event) => setEnvironments((current) => current.map((item, itemIndex) => itemIndex === index ? event.target.value : item))} placeholder={`Ambiente ${index + 1}`} required /></div>{environments.length > 1 ? <ConfirmDeleteButton title="Excluir ambiente?" description="O ambiente será removido desta OS." onConfirm={async () => setEnvironments((current) => current.filter((_, itemIndex) => itemIndex !== index))} /> : null}</div>)}<Button type="button" variant="outline" size="sm" onClick={() => setEnvironments((current) => [...current, ""])}><Plus className="h-4 w-4" />Adicionar ambiente</Button></div>}</section> : null}<div className="grid gap-4 sm:grid-cols-2"><LabeledInput name="scheduled_start" label="Início" type="datetime-local" defaultValue={localDate(visit?.scheduled_start)} required /><LabeledInput name="scheduled_end" label="Término previsto" type="datetime-local" defaultValue={localDate(visit?.scheduled_end)} /><LabeledInput name="contact_name" label="Contato no local" defaultValue={visit?.contact_name ?? ""} /><LabeledInput name="contact_phone" label="Telefone" type="tel" defaultValue={visit?.contact_phone ?? ""} /></div><AddressAutocomplete name="address" label="Local da visita" defaultValue={visit?.address} required /><div className="space-y-2"><Label htmlFor="survey-notes">Observações</Label><Textarea id="survey-notes" name="notes" defaultValue={visit?.notes ?? ""} rows={3} /></div><DialogFooter><Button type="submit" disabled={save.isPending}>{save.isPending ? "Salvando..." : "Salvar visita"}</Button></DialogFooter></form></DialogContent></Dialog>;
}

function VisitDetails({ visit, data, onClose, onChanged }: { visit: Visit | null; data: NonNullable<ReturnType<typeof useSurveyDataShape>>; onClose: () => void; onChanged: () => void }) {
  const [reviewNotes, setReviewNotes] = useState(""); const [files, setFiles] = useState<File[]>([]);
  const [materialRows, setMaterialRows] = useState<Array<{ catalog_item_id: string; quantity: string; notes: string; screwdriver_type_id: string; wrench_size_id: string }>>([]);
  const questions = data.questions.filter((question) => data.sections.some((section) => section.id === question.section_id && section.template_id === visit?.template_id));
  const { data: detail } = useQuery({ queryKey: ["site-survey-detail", visit?.id], enabled: Boolean(visit), queryFn: async () => { const [{ data: responses }, { data: attachments }, { data: logs }, { data: lucHistory }, { data: visitMaterials }] = await Promise.all([supabase.from("site_survey_responses").select("*").eq("visit_id", visit?.id ?? ""), supabase.from("site_survey_attachments").select("*").eq("visit_id", visit?.id ?? "").order("created_at"), supabase.from("site_survey_logs").select("*").eq("visit_id", visit?.id ?? "").order("created_at", { ascending: false }), supabase.from("site_survey_luc_history").select("*").eq("visit_id", visit?.id ?? "").order("valid_from", { ascending: false }), supabase.from("site_survey_visit_materials").select("*").eq("visit_id", visit?.id ?? "").order("created_at")]); return { responses: responses ?? [], attachments: attachments ?? [], logs: logs ?? [], lucHistory: lucHistory ?? [], visitMaterials: visitMaterials ?? [] }; } });
  useEffect(() => { setMaterialRows((detail?.visitMaterials ?? []).map((item) => ({ catalog_item_id: item.catalog_item_id, quantity: String(item.quantity), notes: item.notes ?? "", screwdriver_type_id: item.screwdriver_type_id ?? "none", wrench_size_id: item.wrench_size_id ?? "none" }))); }, [detail?.visitMaterials]);
  if (!visit) return null;
  const updateStatus = async (status: VisitStatus) => { const stamps: Record<string, string> = {}; if (status === "em_andamento") stamps.started_at = new Date().toISOString(); if (status === "em_revisao") stamps.submitted_at = new Date().toISOString(); if (status === "concluida") stamps.completed_at = new Date().toISOString(); if (status === "cancelada") stamps.cancelled_at = new Date().toISOString(); const { error } = await supabase.from("site_survey_visits").update({ status, review_notes: reviewNotes || visit.review_notes, ...stamps }).eq("id", visit.id); if (error) return toast.error(error.message); toast.success(`Visita ${STATUS[status].toLocaleLowerCase("pt-BR")}`); onChanged(); };
  const saveAnswers = async (form: HTMLFormElement) => { const values = new FormData(form); const rows = questions.map((question) => ({ visit_id: visit.id, question_id: question.id, answered_by: data.userId, answer: question.question_type === "checkbox" ? values.get(question.id) === "on" : String(values.get(question.id) ?? "") })); if (rows.length) { const { error } = await supabase.from("site_survey_responses").upsert(rows, { onConflict: "visit_id,question_id" }); if (error) return toast.error(error.message); } const invalidMaterial = materialRows.some((item) => !item.catalog_item_id || !Number.isFinite(Number(item.quantity)) || Number(item.quantity) <= 0); if (invalidMaterial) return toast.error("Informe o item e uma quantidade maior que zero."); const { error: clearError } = await supabase.from("site_survey_visit_materials").delete().eq("visit_id", visit.id); if (clearError) return toast.error(clearError.message); if (materialRows.length) { const { error: materialError } = await supabase.from("site_survey_visit_materials").insert(materialRows.map((item) => ({ visit_id: visit.id, catalog_item_id: item.catalog_item_id, quantity: Number(item.quantity), notes: item.notes.trim() || null, screwdriver_type_id: item.screwdriver_type_id === "none" ? null : item.screwdriver_type_id, wrench_size_id: item.wrench_size_id === "none" ? null : item.wrench_size_id, recorded_by: data.userId }))); if (materialError) return toast.error(materialError.message); } for (const file of files) { const safe = file.name.replace(/[^a-zA-Z0-9._-]/g, "-"); const path = `${visit.id}/${crypto.randomUUID()}-${safe}`; const { error: uploadError } = await supabase.storage.from("site-survey-attachments").upload(path, file); if (uploadError) return toast.error(uploadError.message); const { error } = await supabase.from("site_survey_attachments").insert({ visit_id: visit.id, uploaded_by: data.userId, file_name: file.name, storage_path: path, content_type: file.type, file_size: file.size }); if (error) return toast.error(error.message); } toast.success("Vistoria salva"); setFiles([]); await updateStatus("em_revisao"); };
  const answers = new Map((detail?.responses ?? []).map((response) => [response.question_id, response.answer]));
  return <Dialog open={Boolean(visit)} onOpenChange={(open) => !open && onClose()}><DialogContent className="max-h-[94vh] max-w-4xl overflow-y-auto"><DialogHeader><DialogTitle>Site Survey #{String(visit.survey_number).padStart(6, "0")}</DialogTitle><DialogDescription><MapPin className="mr-1 inline h-3.5 w-3.5" />{visit.address}</DialogDescription></DialogHeader><div className="grid gap-3 sm:grid-cols-3"><Info label="Situação" value={STATUS[visit.status]} /><Info label="Agendamento" value={new Date(visit.scheduled_start).toLocaleString("pt-BR")} /><Info label="Técnico" value={data.technicians.find((item) => item.id === visit.technician_id)?.full_name ?? "—"} /></div>{visit.luc_number ? <SiteSurveyLucManager visitId={visit.id} userId={data.userId} canImport={data.permissions.has("site_survey_agendar") || data.permissions.has("site_survey_editar")} canEdit={data.permissions.has("site_survey_agendar") || data.permissions.has("site_survey_editar") || data.permissions.has("site_survey_executar")} /> : null}{(detail?.lucHistory.length ?? 0) > 0 ? <section className="space-y-2 border-t pt-5"><h3 className="font-bold">Histórico anterior do LUC</h3><div className="divide-y rounded-md border">{detail?.lucHistory.map((entry) => <div key={entry.id} className="grid gap-1 p-3 text-sm sm:grid-cols-[120px_1fr_180px]"><span className="font-medium">LUC {entry.luc_number}</span><span>{entry.shop_name}</span><span className="text-muted-foreground">{new Date(entry.valid_from).toLocaleString("pt-BR")}</span></div>)}</div></section> : null}{visit.status === "agendada" && data.permissions.has("site_survey_executar") ? <Button onClick={() => updateStatus("em_andamento")}><Check className="h-4 w-4" />Iniciar visita</Button> : null}{visit.status === "em_andamento" && data.permissions.has("site_survey_executar") ? <form onSubmit={(event) => { event.preventDefault(); void saveAnswers(event.currentTarget); }} className="space-y-5">{data.sections.filter((section) => section.template_id === visit.template_id).map((section) => <section key={section.id} className="space-y-3 border-t pt-5"><div><h3 className="font-bold">{section.title}</h3>{section.description ? <p className="text-sm text-muted-foreground">{section.description}</p> : null}</div>{questions.filter((question) => question.section_id === section.id).map((question) => <QuestionField key={question.id} question={question} answer={answers.get(question.id)} />)}</section>)}{questions.length === 0 ? <div className="rounded-md border border-dashed p-6 text-center text-sm text-muted-foreground">O checklist será disponibilizado quando as perguntas forem cadastradas.</div> : null}<section className="space-y-3 border-t pt-5"><div className="flex items-center justify-between gap-3"><div><h3 className="font-bold">Material necessário para a instalação</h3><p className="text-sm text-muted-foreground">Selecione todos os itens necessários.</p></div><Button type="button" size="sm" variant="outline" onClick={() => setMaterialRows((current) => [...current, { catalog_item_id: "", quantity: "1", notes: "", screwdriver_type_id: "none", wrench_size_id: "none" }])}><Plus className="h-4 w-4" />Item</Button></div>{materialRows.map((row, index) => { const item = data.catalog.find((entry) => entry.id === row.catalog_item_id); return <div key={`${row.catalog_item_id}-${index}`} className="grid gap-3 rounded-md border p-3 sm:grid-cols-[1.4fr_100px_1fr_auto]"><FormSelect name={`material-${index}`} label="Material ou equipamento" value={row.catalog_item_id || undefined} onChange={(value) => setMaterialRows((current) => current.map((entry, itemIndex) => itemIndex === index ? { ...entry, catalog_item_id: value } : entry))} options={data.catalog.filter((entry) => entry.active)} /><LabeledControlled label="Quantidade" type="number" value={row.quantity} onChange={(value) => setMaterialRows((current) => current.map((entry, itemIndex) => itemIndex === index ? { ...entry, quantity: value } : entry))} />{item?.name === "Chave de fenda" ? <FormSelect name={`screwdriver-${index}`} label="Tipo" value={row.screwdriver_type_id} onChange={(value) => setMaterialRows((current) => current.map((entry, itemIndex) => itemIndex === index ? { ...entry, screwdriver_type_id: value } : entry))} options={data.screwdriverTypes} optional /> : item?.name === "Chave de grifo" ? <FormSelect name={`wrench-${index}`} label="Bitola" value={row.wrench_size_id} onChange={(value) => setMaterialRows((current) => current.map((entry, itemIndex) => itemIndex === index ? { ...entry, wrench_size_id: value } : entry))} options={data.wrenchSizes} optional /> : <LabeledControlled label="Observação" value={row.notes} onChange={(value) => setMaterialRows((current) => current.map((entry, itemIndex) => itemIndex === index ? { ...entry, notes: value } : entry))} />}<ConfirmDeleteButton title="Remover item?" description="O item será retirado da lista desta OS." onConfirm={async () => setMaterialRows((current) => current.filter((_, itemIndex) => itemIndex !== index))} /></div>; })}{materialRows.length === 0 ? <p className="rounded-md border border-dashed p-4 text-sm text-muted-foreground">Nenhum material ou equipamento selecionado.</p> : null}</section><div className="space-y-2"><Label htmlFor="survey-files" className="flex items-center gap-2"><Camera className="h-4 w-4" />Fotos e anexos</Label><Input id="survey-files" type="file" accept="image/*,application/pdf" multiple onChange={(event) => setFiles(Array.from(event.target.files ?? []))} /></div><Button type="submit"><ClipboardCheck className="h-4 w-4" />Salvar e enviar para revisão</Button></form> : null}{(detail?.attachments.length ?? 0) > 0 ? <section className="space-y-2 border-t pt-5"><h3 className="font-bold">Anexos</h3>{detail?.attachments.map((attachment) => <Button key={attachment.id} variant="outline" size="sm" onClick={async () => { const { data: signed } = await supabase.storage.from("site-survey-attachments").createSignedUrl(attachment.storage_path, 600); if (signed?.signedUrl) window.open(signed.signedUrl, "_blank", "noopener,noreferrer"); }}><FileText className="h-4 w-4" />{attachment.file_name}</Button>)}</section> : null}{visit.status === "em_revisao" && data.permissions.has("site_survey_revisar") ? <section className="space-y-3 border-t pt-5"><Label htmlFor="review-notes">Observações da revisão</Label><Textarea id="review-notes" value={reviewNotes} onChange={(event) => setReviewNotes(event.target.value)} /><div className="flex flex-wrap gap-2"><Button onClick={() => updateStatus("concluida")}><Check className="h-4 w-4" />Concluir</Button><Button variant="outline" onClick={() => updateStatus("em_andamento")}><Pencil className="h-4 w-4" />Solicitar ajustes</Button></div></section> : null}{visit.status !== "cancelada" && visit.status !== "concluida" && data.permissions.has("site_survey_editar") ? <Button variant="destructive" onClick={() => updateStatus("cancelada")}><X className="h-4 w-4" />Cancelar visita</Button> : null}{visit.status === "concluida" && data.permissions.has("site_survey_revisar") ? <Button variant="outline" onClick={() => updateStatus("em_andamento")}><Pencil className="h-4 w-4" />Reabrir visita</Button> : null}</DialogContent></Dialog>;
}

function ChecklistAdmin({ data, onChanged }: { data: NonNullable<ReturnType<typeof useSurveyDataShape>>; onChanged: () => void }) {
  const [selected, setSelected] = useState(data.templates[0]?.id ?? "");
  const createTemplate = async (form: HTMLFormElement) => { const values = new FormData(form); const { error } = await supabase.from("site_survey_templates").insert({ name: String(values.get("name")), description: String(values.get("description")) || null, created_by: data.userId }); if (error) return toast.error(error.message); toast.success("Modelo criado"); form.reset(); onChanged(); };
  const createSection = async (form: HTMLFormElement) => { if (!selected) return; const values = new FormData(form); const { error } = await supabase.from("site_survey_sections").insert({ template_id: selected, title: String(values.get("title")), description: String(values.get("description")) || null, position: data.sections.filter((item) => item.template_id === selected).length }); if (error) return toast.error(error.message); toast.success("Seção adicionada"); form.reset(); onChanged(); };
  const createQuestion = async (form: HTMLFormElement, sectionId: string) => { const values = new FormData(form); const options = String(values.get("options") ?? "").split("\n").map((item) => item.trim()).filter(Boolean); const { error } = await supabase.from("site_survey_questions").insert({ section_id: sectionId, prompt: String(values.get("prompt")), question_type: String(values.get("question_type")), required: values.get("required") === "on", options, position: data.questions.filter((item) => item.section_id === sectionId).length }); if (error) return toast.error(error.message); toast.success("Pergunta adicionada"); form.reset(); onChanged(); };
  return <div className="grid gap-6 lg:grid-cols-[320px_1fr]"><Card><CardHeader><CardTitle>Modelos</CardTitle><CardDescription>Cadastre os roteiros de vistoria.</CardDescription></CardHeader><CardContent className="space-y-4"><form onSubmit={(event) => { event.preventDefault(); void createTemplate(event.currentTarget); }} className="space-y-3"><LabeledInput name="name" label="Nome do modelo" required /><div className="space-y-2"><Label>Descrição</Label><Textarea name="description" rows={2} /></div><Button type="submit" size="sm"><Plus className="h-4 w-4" />Criar modelo</Button></form><div className="space-y-1 border-t pt-3">{data.templates.map((template) => <Button key={template.id} variant={selected === template.id ? "secondary" : "ghost"} className="w-full justify-start" onClick={() => setSelected(template.id)}>{template.name}</Button>)}</div></CardContent></Card><div className="space-y-5">{selected ? <><Card><CardHeader><CardTitle>Seções do checklist</CardTitle></CardHeader><CardContent><form onSubmit={(event) => { event.preventDefault(); void createSection(event.currentTarget); }} className="grid gap-3 sm:grid-cols-[1fr_1fr_auto]"><LabeledInput name="title" label="Título da seção" required /><LabeledInput name="description" label="Descrição" /><Button type="submit" className="self-end"><Plus className="h-4 w-4" />Adicionar</Button></form></CardContent></Card>{data.sections.filter((item) => item.template_id === selected).map((section) => <Card key={section.id}><CardHeader><CardTitle>{section.title}</CardTitle>{section.description ? <CardDescription>{section.description}</CardDescription> : null}</CardHeader><CardContent className="space-y-4"><div className="divide-y rounded-md border">{data.questions.filter((item) => item.section_id === section.id).map((question) => <div key={question.id} className="flex items-center justify-between gap-3 p-3"><span className="text-sm">{question.prompt}{question.required ? " *" : ""}</span><Badge variant="outline">{question.question_type}</Badge></div>)}{!data.questions.some((item) => item.section_id === section.id) ? <p className="p-4 text-sm text-muted-foreground">Nenhuma pergunta cadastrada.</p> : null}</div><form onSubmit={(event) => { event.preventDefault(); void createQuestion(event.currentTarget, section.id); }} className="grid gap-3 sm:grid-cols-2"><LabeledInput name="prompt" label="Pergunta" required /><div className="space-y-2"><Label>Tipo de resposta</Label><Select name="question_type" defaultValue="checkbox"><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="checkbox">Caixa de seleção</SelectItem><SelectItem value="text">Texto curto</SelectItem><SelectItem value="textarea">Texto longo</SelectItem><SelectItem value="number">Número</SelectItem><SelectItem value="select">Lista de opções</SelectItem></SelectContent></Select></div><div className="space-y-2"><Label>Opções da lista</Label><Textarea name="options" rows={2} placeholder="Uma opção por linha" /></div><label className="flex items-center gap-2 self-end pb-3 text-sm"><Checkbox name="required" />Obrigatória</label><Button type="submit" size="sm" className="w-fit"><Plus className="h-4 w-4" />Adicionar pergunta</Button></form></CardContent></Card>)}</> : <div className="rounded-md border border-dashed p-10 text-center text-muted-foreground">Crie ou selecione um modelo.</div>}</div></div>;
}

function SurveyCatalogAdmin({ data, onChanged }: { data: NonNullable<ReturnType<typeof useSurveyDataShape>>; onChanged: () => void }) {
  const lists = [
    { key: "catalog", title: "Materiais e equipamentos", table: "site_survey_material_catalog", items: data.catalog },
    { key: "screwdriver", title: "Tipos de chave de fenda", table: "site_survey_screwdriver_types", items: data.screwdriverTypes },
    { key: "wrench", title: "Bitolas de chave de grifo", table: "site_survey_wrench_sizes", items: data.wrenchSizes },
  ] as const;
  const add = async (form: HTMLFormElement, table: string, key: string) => { const values = new FormData(form); const name = String(values.get("name") ?? "").trim(); if (!name || name.length > 120) return toast.error("Informe um nome com até 120 caracteres."); const payload = table === "site_survey_material_catalog" ? { name, category: String(values.get("category")) } : { name }; const { error } = await supabase.from(table as "site_survey_material_catalog").insert(payload as never); if (error) return toast.error(error.message); toast.success("Cadastro adicionado"); form.reset(); onChanged(); };
  return <div className="space-y-5"><div><h2 className="text-xl font-bold">Cadastro</h2><p className="text-sm text-muted-foreground">Diversos</p></div><div className="grid gap-5 lg:grid-cols-3">{lists.map((list) => <Card key={list.key}><CardHeader><CardTitle className="text-base">{list.title}</CardTitle></CardHeader><CardContent className="space-y-4"><form onSubmit={(event) => { event.preventDefault(); void add(event.currentTarget, list.table, list.key); }} className="space-y-3"><LabeledInput name="name" label="Nome" required />{list.key === "catalog" ? <div className="space-y-2"><Label>Categoria</Label><Select name="category" defaultValue="equipamento"><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="material">Material</SelectItem><SelectItem value="equipamento">Equipamento</SelectItem></SelectContent></Select></div> : null}<Button type="submit" size="sm"><Plus className="h-4 w-4" />Adicionar</Button></form><div className="divide-y rounded-md border">{list.items.map((item) => <div key={item.id} className="flex items-center justify-between gap-2 p-3 text-sm"><span>{item.name}</span><ConfirmDeleteButton title={`Excluir ${item.name}?`} description="A exclusão será bloqueada se o cadastro já estiver vinculado a uma OS." onConfirm={async () => { const { error } = await supabase.from(list.table as "site_survey_material_catalog").delete().eq("id", item.id); if (error) return toast.error(error.message); toast.success("Cadastro excluído"); onChanged(); }} /></div>)}</div></CardContent></Card>)}</div></div>;
}

function SurveyProfilesAdmin() {
  const qc = useQueryClient(); const [creating, setCreating] = useState(false); const [filter, setFilter] = useState(""); const { data = [] } = useQuery({ queryKey: ["site-survey-profiles"], queryFn: async () => { const { data, error } = await supabase.from("site_survey_access_profiles").select("*,site_survey_profile_permissions(permission_key,allowed)").order("name"); if (error) throw error; return data; } });
  const save = async (form: HTMLFormElement, profile?: typeof data[number]): Promise<void> => { const values = new FormData(form); const name = String(values.get("name")).trim(); const code = profile?.code ?? name.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, ""); const selected = PERMISSIONS.filter(([key]) => values.get(key) === "on").map(([permission_key]) => ({ profile_code: code, permission_key, allowed: true })); const { error } = await supabase.from("site_survey_access_profiles").upsert({ code, name, active: true }); if (error) { toast.error(error.message); return; } await supabase.from("site_survey_profile_permissions").delete().eq("profile_code", code); if (selected.length) { const { error: permissionError } = await supabase.from("site_survey_profile_permissions").insert(selected); if (permissionError) { toast.error(permissionError.message); return; } } toast.success("Perfil salvo"); qc.invalidateQueries({ queryKey: ["site-survey-profiles"] }); };
  const visible = data.filter((profile) => profile.name.toLocaleLowerCase("pt-BR").includes(filter.toLocaleLowerCase("pt-BR")));
  return <Card><CardHeader className="flex flex-row items-start justify-between gap-4"><div><CardTitle className="flex items-center gap-2"><ShieldCheck className="h-5 w-5" />Perfis de acesso</CardTitle><CardDescription>Adicione ou remova acessos de cada perfil.</CardDescription></div><Button onClick={() => setCreating((current) => !current)}><Plus className="h-4 w-4" />Novo perfil</Button></CardHeader><CardContent className="space-y-4"><div className="relative max-w-sm"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input value={filter} onChange={(event) => setFilter(event.target.value)} placeholder="Filtrar por nome do perfil" className="pl-9" /></div>{creating ? <InlineProfileForm onSave={async (form) => { await save(form); setCreating(false); }} onCancel={() => setCreating(false)} /> : null}{visible.map((profile) => <InlineProfileForm key={profile.code} profile={profile} onSave={save} />)}</CardContent></Card>;
}

function InlineProfileForm({ profile, onSave, onCancel }: { profile?: { code: string; name: string; site_survey_profile_permissions: Array<{ permission_key: string; allowed: boolean }> }; onSave: (form: HTMLFormElement, profile?: any) => Promise<void>; onCancel?: () => void }) {
  const checked = new Set(profile?.site_survey_profile_permissions.filter((item) => item.allowed).map((item) => item.permission_key) ?? []);
  return <form onSubmit={async (event) => { event.preventDefault(); await onSave(event.currentTarget, profile); }} className="space-y-4 rounded-md border border-border p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div className="w-full max-w-sm"><LabeledInput name="name" label={profile ? "Nome do perfil" : "Novo perfil de acesso"} defaultValue={profile?.name ?? ""} required /></div>{profile ? <Badge variant="outline">{profile.site_survey_profile_permissions.length} acessos selecionados</Badge> : null}</div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{PERMISSIONS.map(([key, label]) => <label key={key} className="flex items-center gap-2 rounded-md border p-3 text-sm"><Checkbox name={key} defaultChecked={checked.has(key)} />{label}</label>)}</div><div className="flex justify-end gap-2">{onCancel ? <Button type="button" variant="outline" onClick={onCancel}>Cancelar</Button> : null}<Button type="submit">Salvar perfil</Button></div></form>;
}

function SurveyUsersAdmin() {
  const qc = useQueryClient(); const { data } = useQuery({ queryKey: ["site-survey-users-admin"], queryFn: async () => { const [{ data: accesses }, { data: profiles }, { data: definitions }, { data: surveyProfiles }] = await Promise.all([supabase.from("user_app_access").select("user_id").eq("app_key", "site_survey"), supabase.from("profiles").select("id,full_name,email").is("deleted_at", null).order("full_name"), supabase.from("site_survey_access_profiles").select("code,name").eq("active", true).order("name"), supabase.from("site_survey_user_profiles").select("user_id,profile_code,is_customized")]); const ids = new Set((accesses ?? []).map((item) => item.user_id)); return { users: (profiles ?? []).filter((item) => ids.has(item.id)), definitions: definitions ?? [], surveyProfiles: new Map((surveyProfiles ?? []).map((item) => [item.user_id, item])) }; } });
  const setProfile = async (userId: string, profileCode: string) => { const { error } = await supabase.from("site_survey_user_profiles").upsert({ user_id: userId, profile_code: profileCode, is_customized: false }); if (error) return toast.error(error.message); await supabase.from("site_survey_user_permissions").delete().eq("user_id", userId); toast.success("Perfil atualizado"); qc.invalidateQueries({ queryKey: ["site-survey-users-admin"] }); };
  return <Card><CardHeader><CardTitle>Usuários</CardTitle><CardDescription>Atribua um perfil do Site Survey aos usuários liberados no portal.</CardDescription></CardHeader><CardContent className="space-y-2">{data?.users.map((user) => <div key={user.id} className="grid gap-3 rounded-md border p-3 sm:grid-cols-[1fr_280px] sm:items-center"><div className="min-w-0"><p className="truncate font-medium">{user.full_name || "Sem nome"}</p><p className="truncate text-xs text-muted-foreground">{user.email}</p></div><Select value={data.surveyProfiles.get(user.id)?.profile_code ?? "tecnico"} onValueChange={(value) => void setProfile(user.id, value)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{data.definitions.map((profile) => <SelectItem key={profile.code} value={profile.code}>{profile.name}</SelectItem>)}</SelectContent></Select></div>)}</CardContent></Card>;
}

function SurveyLogs({ names }: { names: { clients: Map<string, string>; projects: Map<string, string>; technicians: Map<string, string> } }) {
  const { data = [] } = useQuery({ queryKey: ["site-survey-logs"], queryFn: async () => { const { data, error } = await supabase.from("site_survey_logs").select("*,site_survey_visits(survey_number,technician_id,client_id,project_id)").order("created_at", { ascending: false }).limit(300); if (error) throw error; return data; } });
  return <Card><CardHeader><CardTitle>Logs</CardTitle><CardDescription>Histórico das alterações nas visitas.</CardDescription></CardHeader><CardContent className="divide-y">{data.map((log) => { const visit = log.site_survey_visits as { survey_number: number; technician_id: string; client_id: string | null; project_id: string | null } | null; return <div key={log.id} className="grid gap-1 py-3 text-sm sm:grid-cols-[160px_160px_1fr]"><span>{new Date(log.created_at).toLocaleString("pt-BR")}</span><span>Survey #{String(visit?.survey_number ?? 0).padStart(6, "0")}</span><span>{log.action.replaceAll("_", " ")} · {names.clients.get(visit?.client_id ?? "") ?? names.projects.get(visit?.project_id ?? "") ?? names.technicians.get(visit?.technician_id ?? "")}</span></div>; })}{!data.length ? <p className="py-8 text-center text-sm text-muted-foreground">Nenhum evento registrado.</p> : null}</CardContent></Card>;
}

function QuestionField({ question, answer }: { question: Question; answer: unknown }) {
  const options = Array.isArray(question.options) ? question.options.filter((item): item is string => typeof item === "string") : [];
  if (question.question_type === "checkbox") return <label className="flex items-center gap-3 rounded-md border p-3 text-sm"><Checkbox name={question.id} defaultChecked={answer === true} required={question.required} />{question.prompt}</label>;
  if (question.question_type === "select") return <div className="space-y-2"><Label>{question.prompt}{question.required ? " *" : ""}</Label><Select name={question.id} defaultValue={typeof answer === "string" ? answer : undefined} required={question.required}><SelectTrigger><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent>{options.map((option) => <SelectItem key={option} value={option}>{option}</SelectItem>)}</SelectContent></Select></div>;
  if (question.question_type === "textarea") return <div className="space-y-2"><Label>{question.prompt}{question.required ? " *" : ""}</Label><Textarea name={question.id} defaultValue={typeof answer === "string" ? answer : ""} required={question.required} /></div>;
  return <LabeledInput name={question.id} label={question.prompt} type={question.question_type === "number" ? "number" : "text"} defaultValue={typeof answer === "string" || typeof answer === "number" ? String(answer) : ""} required={question.required} />;
}

function FormSelect({ name, label, options, defaultValue, value, onChange, optional = false }: { name: string; label: string; options: Named[]; defaultValue?: string; value?: string; onChange?: (value: string) => void; optional?: boolean }) { return <div className="space-y-2"><Label>{label}</Label><Select name={name} value={value} defaultValue={value === undefined ? defaultValue : undefined} onValueChange={onChange} required={!optional}><SelectTrigger><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent>{optional ? <SelectItem value="none">Não se aplica</SelectItem> : null}{options.map((item) => <SelectItem key={item.id} value={item.id}>{item.name}</SelectItem>)}</SelectContent></Select></div>; }
function LabeledInput({ name, label, type = "text", defaultValue, required }: { name: string; label: string; type?: string; defaultValue?: string; required?: boolean }) { return <div className="space-y-2"><Label htmlFor={name}>{label}</Label><Input id={name} name={name} type={type} defaultValue={defaultValue} required={required} /></div>; }
function LabeledControlled({ label, value, onChange, type = "text" }: { label: string; value: string; onChange: (value: string) => void; type?: string }) { return <div className="space-y-2"><Label>{label}</Label><Input type={type} min={type === "number" ? "0.01" : undefined} step={type === "number" ? "0.01" : undefined} value={value} onChange={(event) => onChange(event.target.value)} /></div>; }
function Info({ label, value }: { label: string; value: string }) { return <div className="border-l-2 border-primary pl-3"><p className="text-xs text-muted-foreground">{label}</p><p className="text-sm font-medium">{value}</p></div>; }
function useSurveyDataShape() { return undefined as unknown as { userId: string; visits: Visit[]; clients: ClientOption[]; clientCategories: ClientCategory[]; projects: ProjectOption[]; units: Array<Named & { client_id: string }>; technicians: Profile[]; templates: Template[]; sections: Section[]; questions: Question[]; catalog: CatalogItem[]; screwdriverTypes: Named[]; wrenchSizes: Named[]; permissions: Set<string>; profileName: string; isErpAdmin: boolean } | undefined; }